351	    private GraphChecks() {
352	    }
353	
354	    static void validateVertexCount(int vertexCount) {
355	        if (vertexCount < 0) {
356	            throw new IllegalArgumentException("Vertex count must be non-negative");
357	        }
358	    }
359	
360	    static void validateVertex(int vertex, int vertexCount, String label) {
361	        if (vertex < 0 || vertex >= vertexCount) {
362	            throw new IllegalArgumentException(label + " vertex out of range: " + vertex);
363	        }
364	    }
365	
366	    static void validateWeight(int weight) {
367	        if (weight < 0) {
368	            throw new IllegalArgumentException("Dijkstra's algorithm requires non-negative edge weights");
369	        }
370	    }
371	
372	    static int addDistances(int left, int right) {
373	        long sum = (long) left + right;
374	        if (sum > Integer.MAX_VALUE) {
375	            throw new ArithmeticException("Shortest path exceeds supported integer range");
376	        }
377	        return (int) sum;
378	    }
379	}

