331	    private GraphChecks() {
332	    }
333	
334	    static void validateVertexCount(int vertexCount) {
335	        if (vertexCount < 0) {
336	            throw new IllegalArgumentException("Vertex count must be non-negative");
337	        }
338	    }
339	
340	    static void validateVertex(int vertex, int vertexCount, String label) {
341	        if (vertex < 0 || vertex >= vertexCount) {
342	            throw new IllegalArgumentException(label + " vertex out of range: " + vertex);
343	        }
344	    }
345	
346	    static void validateWeight(int weight) {
347	        if (weight < 0) {
348	            throw new IllegalArgumentException("Dijkstra's algorithm requires non-negative edge weights");
349	        }
350	    }
351	
352	    static int addDistances(int left, int right) {
353	        long sum = (long) left + right;
354	        if (sum > Integer.MAX_VALUE) {
355	            throw new ArithmeticException("Shortest path exceeds supported integer range");
356	        }
357	        return (int) sum;
358	    }
359	}
